// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {StrictRLP} from "./StrictRLP.sol";

/// @notice Canonical hexary MPT inclusion/non-inclusion verification; bounded inputs.
library MerklePatricia {
    error BadTrieProof();
    function get(
        bytes32 root,
        bytes memory key,
        bytes[] memory proof
    ) internal pure returns (bool present, bytes memory value) {
        if (key.length == 0 || key.length > 64 || proof.length > 128)
            revert BadTrieProof();
        if (root == keccak256(hex"80")) {
            if (proof.length != 0) revert BadTrieProof();
            return (false, hex"");
        }
        bytes memory expected = abi.encodePacked(root);
        uint256 used;
        uint256 position;
        bool rootNode = true;
        for (uint256 steps; steps <= key.length * 2 + 1; ++steps) {
            bytes memory node;
            if (expected.length == 32) {
                if (used >= proof.length) revert BadTrieProof();
                node = proof[used++];
                if (
                    node.length > 65536 ||
                    (!rootNode && node.length < 32) ||
                    keccak256(node) != bytes32(expected)
                ) revert BadTrieProof();
            } else {
                if (expected.length == 0 || expected.length >= 32)
                    revert BadTrieProof();
                node = expected;
                // Some clients also list inline children. Consume only an exact duplicate.
                if (
                    used < proof.length &&
                    keccak256(proof[used]) == keccak256(node)
                ) ++used;
            }
            rootNode = false;
            StrictRLP.Item[] memory f = StrictRLP.children(node, 17);
            if (f.length == 17) {
                if (position == key.length * 2) {
                    if (used != proof.length || f[16].list)
                        revert BadTrieProof();
                    return (
                        f[16].length != 0,
                        StrictRLP.slice(node, f[16].payload, f[16].length)
                    );
                }
                uint256 index = nibble(key, position++);
                expected = child(node, f[index]);
                if (expected.length == 0) {
                    if (used != proof.length) revert BadTrieProof();
                    return (false, hex"");
                }
            } else if (f.length == 2) {
                if (f[0].list || f[0].length == 0) revert BadTrieProof();
                bytes memory compact = StrictRLP.slice(
                    node,
                    f[0].payload,
                    f[0].length
                );
                uint256 flag = uint8(compact[0]) >> 4;
                if (flag > 3) revert BadTrieProof();
                bool odd = (flag & 1) != 0;
                bool leaf = (flag & 2) != 0;
                if (!odd && (uint8(compact[0]) & 15) != 0)
                    revert BadTrieProof();
                uint256 offset = odd ? 1 : 2;
                uint256 length = compact.length * 2 - offset;
                if (!leaf && length == 0) revert BadTrieProof();
                bool matches = position + length <= key.length * 2;
                for (uint256 i; matches && i < length; ++i)
                    if (
                        nibble(compact, offset + i) != nibble(key, position + i)
                    ) matches = false;
                if (!matches) {
                    if (used != proof.length) revert BadTrieProof();
                    return (false, hex"");
                }
                position += length;
                if (leaf) {
                    if (used != proof.length || f[1].list)
                        revert BadTrieProof();
                    if (position != key.length * 2) return (false, hex"");
                    return (
                        true,
                        StrictRLP.slice(node, f[1].payload, f[1].length)
                    );
                }
                expected = child(node, f[1]);
                if (expected.length == 0) revert BadTrieProof();
            } else revert BadTrieProof();
        }
        revert BadTrieProof();
    }
    function child(
        bytes memory node,
        StrictRLP.Item memory p
    ) private pure returns (bytes memory) {
        if (p.list) {
            if (p.size >= 32) revert BadTrieProof();
            return StrictRLP.slice(node, p.start, p.size);
        }
        if (p.length != 0 && p.length != 32) revert BadTrieProof();
        return StrictRLP.slice(node, p.payload, p.length);
    }
    function nibble(
        bytes memory data,
        uint256 at
    ) private pure returns (uint256) {
        uint256 b = uint8(data[at / 2]);
        return at % 2 == 0 ? b >> 4 : b & 15;
    }
}

contracts/proof/RootInbox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {StrictRLP} from "./StrictRLP.sol";
interface IAttestcoinBlockProver {
    struct Sibling {
        bytes32 hash;
        bool isLeft;
    }
    struct MerkleProof {
        bytes32 root;
        Sibling[] siblings;
    }
    struct ContinuityProof {
        bytes32 lowerEndpointDigest;
        bytes32[] roots;
    }
    function verify(
        uint64 chainKey,
        uint64 height,
        bytes calldata txBytes,
        MerkleProof calldata merkle,
        ContinuityProof calldata continuity
    ) external view returns (bool);
}
/// Roots enter only through verified HeaderAnchor receipts. No administrator root setter.
contract RootInbox {
    struct Log {
        address emitter;
        bytes32[] topics;
        bytes data;
    }
    struct Header {
        uint64 height;
        uint64 timestamp;
        bytes32 parentHash;
        bytes32 stateRoot;
        bytes32 transactionsRoot;
        bytes32 receiptsRoot;
    }
    IAttestcoinBlockProver public immutable prover;
    uint64 public immutable chainKey;
    uint256 public immutable sourceChainId;
    address public immutable anchor;
    bytes32 public immutable sourceDomain;
    mapping(bytes32 => Header) private roots;
    mapping(uint64 => bytes32) public canonicalHash;
    bytes32 public constant ANCHOR_EVENT =
        keccak256("HeaderAnchored(uint256,uint256,bytes32)");
    error InvalidProof();
    error InvalidAnchor();
    error InvalidHeader();
    error Conflict();
    event HeaderAccepted(
        bytes32 indexed sourceDomain,
        uint64 indexed height,
        bytes32 indexed blockHash,
        bytes32 stateRoot,
        bytes32 transactionsRoot,
        bytes32 receiptsRoot,
        uint64 timestamp
    );
    constructor(
        address nativeProver,
        uint64 sourceChainKey,
        uint256 ethereumChainId,
        address headerAnchor
    ) {
        if (
            nativeProver == address(0) ||
            headerAnchor == address(0) ||
            ethereumChainId == 0
        ) revert InvalidAnchor();
        prover = IAttestcoinBlockProver(nativeProver);
        chainKey = sourceChainKey;
        sourceChainId = ethereumChainId;
        anchor = headerAnchor;
        sourceDomain = keccak256(
            abi.encode(
                block.chainid,
                address(this),
                nativeProver,
                sourceChainKey,
                ethereumChainId,
                headerAnchor
            )
        );
    }
    function accept(
        uint64 anchorHeight,
        bytes calldata txBytes,
        IAttestcoinBlockProver.MerkleProof calldata merkle,
        IAttestcoinBlockProver.ContinuityProof calldata continuity,
        bytes calldata fullHeader
    ) external returns (bytes32 hash) {
        if (!prover.verify(chainKey, anchorHeight, txBytes, merkle, continuity))
            revert InvalidProof();
        (uint8 kind, bytes[] memory chunks) = abi.decode(
            txBytes,
            (uint8, bytes[])
        );
        if (kind > 4 || chunks.length != (kind <= 2 ? 3 : 4))
            revert InvalidAnchor();
        (uint8 status, , Log[] memory logs, ) = abi.decode(
            chunks[chunks.length - 1],
            (uint8, uint64, Log[], bytes)
        );
        if (status != 1 || logs.length > 1024) revert InvalidAnchor();
        hash = keccak256(fullHeader);
        Header memory h = parseHeader(fullHeader);
        if (h.height >= anchorHeight || anchorHeight - h.height > 256)
            revert InvalidAnchor();
        uint256 matches;
        for (uint256 i; i < logs.length; ++i) {
            Log memory l = logs[i];
            if (
                l.emitter == anchor &&
                l.topics.length == 3 &&
                l.topics[0] == ANCHOR_EVENT &&
                uint256(l.topics[1]) == sourceChainId &&
                uint256(l.topics[2]) == h.height &&
                l.data.length == 32 &&
                abi.decode(l.data, (bytes32)) == hash
            ) ++matches;
        }
        if (matches != 1) revert InvalidAnchor();
        store(hash, h);
    }
    function acceptParent(
        bytes32 acceptedChild,
        bytes calldata parentRlp
    ) external returns (bytes32 parentHash) {
        Header memory child = roots[acceptedChild];
        if (
            acceptedChild == bytes32(0) ||
            canonicalHash[child.height] != acceptedChild
        ) revert InvalidHeader();
        parentHash = keccak256(parentRlp);
        if (parentHash != child.parentHash) revert InvalidHeader();
        Header memory p = parseHeader(parentRlp);
        if (
            uint256(p.height) + 1 != child.height ||
            p.timestamp >= child.timestamp
        ) revert InvalidHeader();
        store(parentHash, p);
    }
    function getHeader(bytes32 hash) external view returns (Header memory h) {
        h = roots[hash];
        if (hash == bytes32(0) || canonicalHash[h.height] != hash)
            revert InvalidHeader();
    }
    function store(bytes32 hash, Header memory h) private {
        bytes32 old = canonicalHash[h.height];
        if (old != bytes32(0) && old != hash) revert Conflict();
        roots[hash] = h;
        canonicalHash[h.height] = hash;
        emit HeaderAccepted(
            sourceDomain,
            h.height,
            hash,
            h.stateRoot,
            h.transactionsRoot,
            h.receiptsRoot,
            h.timestamp
        );
    }
    function parseHeader(
        bytes memory data
    ) public pure returns (Header memory h) {
        if (data.length > 4096) revert InvalidHeader();
        StrictRLP.Item[] memory f = StrictRLP.children(data, 21);
        if (
            f.length != 15 &&
            f.length != 16 &&
            f.length != 17 &&
            f.length != 20 &&
            f.length != 21
        ) revert InvalidHeader();
        h.parentHash = StrictRLP.hash32(data, f[0]);
        h.stateRoot = StrictRLP.hash32(data, f[3]);
        h.transactionsRoot = StrictRLP.hash32(data, f[4]);
        h.receiptsRoot = StrictRLP.hash32(data, f[5]);
        uint256 height = StrictRLP.scalar(data, f[8]);
        uint256 timestamp = StrictRLP.scalar(data, f[11]);
        if (height > type(uint64).max || timestamp > type(uint64).max)
            revert InvalidHeader();
        h.height = uint64(height);
        h.timestamp = uint64(timestamp);
    }
}

contracts/proof/StateProofVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
import {RootInbox} from "./RootInbox.sol";
import {StrictRLP} from "./StrictRLP.sol";
import {MerklePatricia} from "./MerklePatricia.sol";

/// @notice Generic historical facts. This contract does NOT interpret USDC payment outcomes.
contract StateProofVerifier {
    struct StorageFact {
        bool accountPresent;
        bool slotPresent;
        bytes32 codeHash;
        bytes32 storageRoot;
        uint256 value;
        uint64 height;
        uint64 timestamp;
    }
    RootInbox public immutable inbox;
    error InvalidAccount();
    error InvalidValue();
    error MissingReceipt();
    constructor(address rootInbox) {
        if (rootInbox == address(0)) revert InvalidAccount();
        inbox = RootInbox(rootInbox);
    }
    function storageFact(
        bytes32 blockHash,
        address account,
        bytes32 slot,
        bytes[] calldata accountProof,
        bytes[] calldata slotProof
    ) external view returns (StorageFact memory f) {
        RootInbox.Header memory h = inbox.getHeader(blockHash);
        f.height = h.height;
        f.timestamp = h.timestamp;
        bytes memory accountValue;
        (f.accountPresent, accountValue) = accountAt(
            h.stateRoot,
            account,
            accountProof
        );
        if (!f.accountPresent) {
            if (slotProof.length != 0) revert InvalidAccount();
            return f;
        }
        StrictRLP.Item[] memory fields = StrictRLP.children(accountValue, 4);
        if (fields.length != 4) revert InvalidAccount();
        StrictRLP.scalar(accountValue, fields[0]);
        StrictRLP.scalar(accountValue, fields[1]);
        f.storageRoot = StrictRLP.hash32(accountValue, fields[2]);
        f.codeHash = StrictRLP.hash32(accountValue, fields[3]);
        bytes memory value;
        (f.slotPresent, value) = MerklePatricia.get(
            f.storageRoot,
            abi.encodePacked(keccak256(abi.encodePacked(slot))),
            slotProof
        );
        if (f.slotPresent) {
            StrictRLP.Item memory scalar = StrictRLP.item(value, 0);
            if (scalar.size != value.length) revert InvalidValue();
            f.value = StrictRLP.scalar(value, scalar);
        }
    }
    function accountAt(
        bytes32 stateRoot,
        address account,
        bytes[] memory nodes
    ) internal pure returns (bool, bytes memory) {
        return
            MerklePatricia.get(
                stateRoot,
                abi.encodePacked(keccak256(abi.encodePacked(account))),
                nodes
            );
    }
    function receipt(
        bytes32 blockHash,
        uint256 transactionIndex,
        bytes[] calldata receiptProof
    ) external view returns (bytes memory raw, uint64 timestamp) {
        RootInbox.Header memory h = inbox.getHeader(blockHash);
        bool present;
        (present, raw) = MerklePatricia.get(
            h.receiptsRoot,
            indexKey(transactionIndex),
            receiptProof
        );
        if (!present) revert MissingReceipt();
        return (raw, h.timestamp);
    }
    function indexKey(uint256 value) public pure returns (bytes memory out) {
        if (value == 0) return hex"80";
        if (value < 128) {
            out = new bytes(1);
            out[0] = bytes1(uint8(value));
            return out;
        }
        uint256 x = value;
        uint256 n;
        while (x != 0) {
            ++n;
            x >>= 8;
        }
        out = new bytes(n + 1);
        out[0] = bytes1(uint8(128 + n));
        for (uint256 i; i < n; ++i)
            out[n - i] = bytes1(uint8(value >> (i * 8)));
    }
}

contracts/proof/StrictRLP.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;
library StrictRLP {
    error InvalidRLP();
    struct Item {
        uint256 start;
        uint256 size;
        uint256 payload;
        uint256 length;
        bool list;
    }
    function item(
        bytes memory d,
        uint256 s
    ) internal pure returns (Item memory o) {
        if (s >= d.length) revert InvalidRLP();
        uint256 b = uint8(d[s]);
        o.start = s;
        if (b < 128) {
            o.payload = s;
            o.length = 1;
            o.size = 1;
            return o;
        }
        uint256 p;
        if (b <= 183) {
            p = 1;
            o.length = b - 128;
        } else if (b <= 191) {
            p = 1 + b - 183;
            o.length = longLength(d, s + 1, p - 1);
            if (o.length < 56) revert InvalidRLP();
        } else if (b <= 247) {
            p = 1;
            o.length = b - 192;
            o.list = true;
        } else {
            p = 1 + b - 247;
            o.length = longLength(d, s + 1, p - 1);
            if (o.length < 56) revert InvalidRLP();
            o.list = true;
        }
        if (p > d.length - s || o.length > d.length - s - p)
            revert InvalidRLP();
        o.payload = s + p;
        o.size = p + o.length;
        if (!o.list && o.length == 1 && uint8(d[o.payload]) < 128)
            revert InvalidRLP();
    }
    function longLength(
        bytes memory d,
        uint256 a,
        uint256 n
    ) private pure returns (uint256 v) {
        if (n == 0 || n > 8 || a >= d.length || n > d.length - a || d[a] == 0)
            revert InvalidRLP();
        for (uint256 i; i < n; ++i) v = (v << 8) | uint8(d[a + i]);
    }
    function children(
        bytes memory d,
        uint256 max
    ) internal pure returns (Item[] memory out) {
        Item memory top = item(d, 0);
        if (!top.list || top.size != d.length) revert InvalidRLP();
        out = new Item[](max);
        uint256 c = top.payload;
        uint256 end = c + top.length;
        uint256 n;
        while (c < end) {
            if (n == max) revert InvalidRLP();
            Item memory x = item(d, c);
            if (x.size > end - c) revert InvalidRLP();
            out[n++] = x;
            c += x.size;
        }
        if (c != end) revert InvalidRLP();
        assembly {
            mstore(out, n)
        }
    }
    function scalar(
        bytes memory d,
        Item memory p
    ) internal pure returns (uint256 v) {
        if (p.list || p.length > 32 || (p.length > 0 && d[p.payload] == 0))
            revert InvalidRLP();
        for (uint256 i; i < p.length; ++i)
            v = (v << 8) | uint8(d[p.payload + i]);
    }
    function hash32(
        bytes memory d,
        Item memory p
    ) internal pure returns (bytes32 v) {
        if (p.list || p.length != 32) revert InvalidRLP();
        uint256 a = p.payload;
        assembly {
            v := mload(add(add(d, 32), a))
        }
    }
    function slice(
        bytes memory d,
        uint256 a,
        uint256 n
    ) internal pure returns (bytes memory out) {
        if (a > d.length || n > d.length - a) revert InvalidRLP();
        out = new bytes(n);
        for (uint256 i; i < n; ++i) out[i] = d[a + i];
    }
}

contracts/source/GoalRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

interface IERC3009 {
    function balanceOf(address account) external view returns (uint256);
    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes calldata signature
    ) external;
    function transfer(address to, uint256 value) external returns (bool);
}

/// @title GoalRouter — source-chain at-most-once gate for a payment goal.
///
/// @notice This is the contract that makes "the same payment goal is paid at most
/// once" true rather than merely asserted. Every compliant execution for a goal
/// `G` must go through `fill`, and `fills[G]` can only move from empty to set,
/// exactly once, ever. A second executor arriving on a later round reverts here
/// and spends no tokens, which is what allows the CTC side to hand a goal to a
/// replacement executor without risking a second real payment.
///
/// The goal id is derived from terms that both chains can compute independently,
/// so no cross-chain read is needed to agree on identity. Round number and the
/// source payment deadline `T` are bound into the ERC-3009 nonce, so a signed
/// authorization cannot be replayed onto a different goal, a different round, a
/// different winner or a different deadline, and cannot be redirected to pay the
/// final recipient outside this router.
///
/// Scope: one immutable recipient and exact amount per goal. Nothing here stops a
/// third party from gifting tokens to the recipient directly; the guarantee is
/// about compliant executions of `G`, not about the recipient's balance.
contract GoalRouter {
    /// Terms that identify a payment goal. Must be byte-identical to the terms
    /// the CTC-side escrow hashes, or the produced fact will not match any goal.
    struct GoalRef {
        uint256 ctcChainId;
        address escrow;
        address owner;
        bytes32 businessRef;
        address token;
        address recipient;
        uint256 amount;
    }

    struct Authorization {
        address from;
        uint256 validAfter;
        uint256 validBefore;
        bytes signature;
    }

    struct Fill {
        uint32 roundNumber;
        uint64 payBy;
        uint64 filledAt;
        address winner;
        address payer;
    }

    bytes32 public constant FILL_NONCE_DOMAIN =
        keccak256("StateLift.GoalRouter.fillNonce.v1");

    /// The one-shot record. Empty `filledAt` means the goal is still unfilled.
    mapping(bytes32 => Fill) private fills;

    error AlreadyFilled();
    error RoundExpired();
    error InvalidTerms();
    error ExactAmountRequired();

    /// The single fact the CTC side settles against.
    event GoalFilled(
        bytes32 indexed goalId,
        uint32 indexed roundNumber,
        address indexed winner,
        address recipient,
        uint256 amount,
        address payer,
        uint64 payBy
    );

    function goalIdOf(GoalRef calldata g) public pure returns (bytes32) {
        return keccak256(abi.encode(g));
    }

    /// Deterministic ERC-3009 nonce. Binding these fields means the executor's
    /// signature is only usable for this goal, this round, this winner and this
    /// deadline, through this router.
    function fillNonce(
        bytes32 goalId,
        uint32 roundNumber,
        address winner,
        uint64 payBy
    ) public view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    FILL_NONCE_DOMAIN,
                    block.chainid,
                    address(this),
                    goalId,
                    roundNumber,
                    winner,
                    payBy
                )
            );
    }

    function fillOf(bytes32 goalId) external view returns (Fill memory) {
        return fills[goalId];
    }

    function isFilled(bytes32 goalId) external view returns (bool) {
        return fills[goalId].filledAt != 0;
    }

    /// Executes the one compliant payment for `g`. Reverts entirely — spending no
    /// tokens — if the goal was already filled or the round deadline has passed.
    function fill(
        GoalRef calldata g,
        uint32 roundNumber,
        uint64 payBy,
        address winner,
        Authorization calldata auth
    ) external returns (bytes32 goalId) {
        goalId = goalIdOf(g);

        // Order matters: the one-shot gate is checked before any token movement,
        // so a relay attempt on an already-filled goal costs gas and nothing else.
        if (fills[goalId].filledAt != 0) revert AlreadyFilled();
        if (block.timestamp >= payBy) revert RoundExpired();
        if (
            roundNumber == 0 ||
            winner == address(0) ||
            auth.from == address(0) ||
            g.token == address(0) ||
            g.recipient == address(0) ||
            g.escrow == address(0) ||
            g.owner == address(0) ||
            g.ctcChainId == 0 ||
            g.businessRef == bytes32(0) ||
            g.amount == 0 ||
            g.recipient == g.token ||
            g.recipient == address(this) ||
            auth.from == g.recipient
        ) revert InvalidTerms();

        IERC3009 token = IERC3009(g.token);
        uint256 routerBefore = token.balanceOf(address(this));
        uint256 recipientBefore = token.balanceOf(g.recipient);

        token.receiveWithAuthorization(
            auth.from,
            address(this),
            g.amount,
            auth.validAfter,
            auth.validBefore,
            fillNonce(goalId, roundNumber, winner, payBy),
            auth.signature
        );
        // Exact-amount discipline: a token that delivers less (or more) than the
        // goal amount must not be reported as a compliant payment.
        if (token.balanceOf(address(this)) != routerBefore + g.amount)
            revert ExactAmountRequired();

        token.transfer(g.recipient, g.amount);
        if (token.balanceOf(g.recipient) != recipientBefore + g.amount)
            revert ExactAmountRequired();
        if (token.balanceOf(address(this)) != routerBefore)
            revert ExactAmountRequired();

        fills[goalId] = Fill({
            roundNumber: roundNumber,
            payBy: payBy,
            filledAt: uint64(block.timestamp),
            winner: winner,
            payer: auth.from
        });

        emit GoalFilled(
            goalId,
            roundNumber,
            winner,
            g.recipient,
            g.amount,
            auth.from,
            payBy
        );
    }
}
